"use strict";(globalThis.webpackChunkos_1_docs=globalThis.webpackChunkos_1_docs||[]).push([[557],{9328(i){i.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/os1-docs/","label":"Operacijski sustavi 1","docId":"intro","unlisted":false},{"type":"category","label":"Ljuske za rad s OS","items":[{"type":"link","href":"/os1-docs/bash/bash-1","label":"Ljuske za rad s OS 1","docId":"bash/bash-1","unlisted":false},{"type":"link","href":"/os1-docs/bash/bash-2","label":"Ljuske za rad s OS 2","docId":"bash/bash-2","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/os1-docs/bash/"},{"type":"category","label":"Sistemski pozivi","items":[{"type":"link","href":"/os1-docs/sistemski-pozivi/sistemski-pozivi-1","label":"Sistemski pozivi 1","docId":"sistemski-pozivi/sistemski-pozivi-1","unlisted":false},{"type":"link","href":"/os1-docs/sistemski-pozivi/sistemski-pozivi-2","label":"Sistemski pozivi 2","docId":"sistemski-pozivi/sistemski-pozivi-2","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/os1-docs/sistemski-pozivi/"},{"type":"category","label":"Procesi","items":[{"type":"link","href":"/os1-docs/procesi/procesi-1","label":"Procesi 1","docId":"procesi/procesi-1","unlisted":false},{"type":"link","href":"/os1-docs/procesi/procesi-2","label":"Procesi 2","docId":"procesi/procesi-2","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/os1-docs/procesi/"},{"type":"link","href":"/os1-docs/dretve/","label":"Dretve","docId":"dretve/index","unlisted":false},{"type":"category","label":"Me\u0111uprocesna komunikacija","items":[{"type":"link","href":"/os1-docs/meduprocesna-komunikacija/dijeljena-memorija","label":"Dijeljena memorija (Shared memory)","docId":"meduprocesna-komunikacija/dijeljena-memorija","unlisted":false},{"type":"link","href":"/os1-docs/meduprocesna-komunikacija/memorijsko-mapiranje","label":"Memorijsko mapiranje (Mapped memory)","docId":"meduprocesna-komunikacija/memorijsko-mapiranje","unlisted":false},{"type":"link","href":"/os1-docs/meduprocesna-komunikacija/cjevovod","label":"Cjevovod (Pipe)","docId":"meduprocesna-komunikacija/cjevovod","unlisted":false},{"type":"link","href":"/os1-docs/meduprocesna-komunikacija/imenovani-cjevovod","label":"Imenovani cjevovod (Named pipe, FIFO)","docId":"meduprocesna-komunikacija/imenovani-cjevovod","unlisted":false},{"type":"link","href":"/os1-docs/meduprocesna-komunikacija/komunikacija-porukama","label":"Komunikacija porukama (Message queues)","docId":"meduprocesna-komunikacija/komunikacija-porukama","unlisted":false},{"type":"link","href":"/os1-docs/meduprocesna-komunikacija/signali","label":"Signali (Signals)","docId":"meduprocesna-komunikacija/signali","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/os1-docs/meduprocesna-komunikacija/"}]},"docs":{"bash/bash-1":{"id":"bash/bash-1","title":"Ljuske za rad s OS 1","description":"Ljuska (shell) je korisni\u010dki program za interakciju s operacijskim sustavom. Korisnik unosi naredbe putem CLI, ljuska ih interpretira, a jezgra izvr\u0161ava. Bash je jedna od naj\u010de\u0161\u0107e kori\u0161tenih ljuski na Linux sustavima, a mo\u017ee se koristiti i kao programski (skriptni) jezik za automatizaciju zadataka.","sidebar":"tutorialSidebar"},"bash/bash-2":{"id":"bash/bash-2","title":"Ljuske za rad s OS 2","description":"Bash skripte","sidebar":"tutorialSidebar"},"bash/index":{"id":"bash/index","title":"Ljuske za rad s OS","description":"","sidebar":"tutorialSidebar"},"dretve/index":{"id":"dretve/index","title":"Dretve","description":"Vi\u0161edretvenost nam omogu\u0107uje postojanje vi\u0161e neovisnih tokova instrukcija koji se unutar jednog procesa mogu izvr\u0161avati istovremeno.","sidebar":"tutorialSidebar"},"intro":{"id":"intro","title":"Operacijski sustavi 1","description":"Ove stranice namijenjene su studentima kolegija Operacijski sustavi 1 kao vodi\u010d kroz laboratorijske vje\u017ebe i materijale. Kodove zadataka mo\u017eete preuzeti sa slu\u017ebene Merlin stranice kolegija.","sidebar":"tutorialSidebar"},"meduprocesna-komunikacija/cjevovod":{"id":"meduprocesna-komunikacija/cjevovod","title":"Cjevovod (Pipe)","description":"Cjevovod se koristi za jednosmjernu komunikaciju izme\u0111u parent i child procesa. Ovakav tip komunikacijskog kanala ponekad se naziva anonymous/unnamed pipe. Do sada ste se susretali s cjevovodima u Bashu kao mehanizmom redirekcije standardnog izlaza jedne naredbe u standardni ulaz druge naredbe, npr.:","sidebar":"tutorialSidebar"},"meduprocesna-komunikacija/dijeljena-memorija":{"id":"meduprocesna-komunikacija/dijeljena-memorija","title":"Dijeljena memorija (Shared memory)","description":"Dijeljena memorija je najjednostavniji i najefikasniji oblik me\u0111uprocesne komunikacije.","sidebar":"tutorialSidebar"},"meduprocesna-komunikacija/imenovani-cjevovod":{"id":"meduprocesna-komunikacija/imenovani-cjevovod","title":"Imenovani cjevovod (Named pipe, FIFO)","description":"Imenovani cjevovod je sli\u010dan prethodno navedenoj tehnici, uz neke dodatne mogu\u0107nosti. Uobi\u010dajeno nazivlje za ovakav tip komunikacijskog kanala je named pipe/FIFO.","sidebar":"tutorialSidebar"},"meduprocesna-komunikacija/index":{"id":"meduprocesna-komunikacija/index","title":"Me\u0111uprocesna komunikacija","description":"Me\u0111uprocesna komunikacija (Inter-process communication, IPC), predstavlja skup mehanizama koje OS pru\u017ea procesima kako bi mogli u\u010dinkovito upravljati dijeljenim resursima i me\u0111usobno razmjenjivati podatke.","sidebar":"tutorialSidebar"},"meduprocesna-komunikacija/komunikacija-porukama":{"id":"meduprocesna-komunikacija/komunikacija-porukama","title":"Komunikacija porukama (Message queues)","description":"Komunikacija porukama koristi strukturu podataka u kojoj procesi mogu pohranjivati poruke koje \u0107e drugi procesi kasnije pro\u010ditati. Ovaj koncept nalikuje na FIFO, a koristi se na sli\u010dan na\u010din kao dijeljena memorija (generiranje jedinstvenog klju\u010da uz ftok, dohva\u0107anje identifikatora uz msgget, slanje poruka uz msgsnd, primanje poruka uz msgrcv i uklanjanje queuea uz msgctl).","sidebar":"tutorialSidebar"},"meduprocesna-komunikacija/memorijsko-mapiranje":{"id":"meduprocesna-komunikacija/memorijsko-mapiranje","title":"Memorijsko mapiranje (Mapped memory)","description":"Memorijsko mapiranje je tehnika koja omogu\u0107ava povezivanje adresnog prostora procesa i nekog drugog resursa na sustavu, naj\u010de\u0161\u0107e datoteke pohranjene na disku. Procesi tada mogu pristupati sadr\u017eaju datoteke kao obi\u010dnom polju u memoriji (pokaziva\u010du), bez kori\u0161tenja sistemskih poziva read i write.","sidebar":"tutorialSidebar"},"meduprocesna-komunikacija/signali":{"id":"meduprocesna-komunikacija/signali","title":"Signali (Signals)","description":"Sa signalima smo ve\u0107 radili u vje\u017ebi o pregledu i terminiranju procesa. Najjednostavniji na\u010din slanja signala me\u0111u procesima je kill naredba.","sidebar":"tutorialSidebar"},"procesi/index":{"id":"procesi/index","title":"Procesi","description":"","sidebar":"tutorialSidebar"},"procesi/procesi-1":{"id":"procesi/procesi-1","title":"Procesi 1","description":"\u0160to su procesi?","sidebar":"tutorialSidebar"},"procesi/procesi-2":{"id":"procesi/procesi-2","title":"Procesi 2","description":"Jezgra pokre\u0107e init proces pri pokretanju sustava, a taj proces onda naknadno stvara sve ostale procese. Tako nastaje hijerarhijska struktura sli\u010dna (obiteljskom) stablu, gdje svaki proces ima jednog roditelja i mo\u017ee imati vi\u0161e djece.","sidebar":"tutorialSidebar"},"sistemski-pozivi/index":{"id":"sistemski-pozivi/index","title":"Sistemski pozivi","description":"","sidebar":"tutorialSidebar"},"sistemski-pozivi/sistemski-pozivi-1":{"id":"sistemski-pozivi/sistemski-pozivi-1","title":"Sistemski pozivi 1","description":"Jezgreni i korisni\u010dki na\u010din rada","sidebar":"tutorialSidebar"},"sistemski-pozivi/sistemski-pozivi-2":{"id":"sistemski-pozivi/sistemski-pozivi-2","title":"Sistemski pozivi 2","description":"Pro\u0161li smo tjedan govorili o tome kako procesori koriste razli\u010dite razine privilegija kako bi se osigurala stabilnost sustava. Razlikovali smo jezgreni i korisni\u010dki na\u010din rada i predstavili sistemske pozive kao su\u010delje putem kojeg korisni\u010dki programi komuniciraju s OS-om i zahtijevaju njegove usluge. Naveli smo vrste sistemskih poziva, upoznali se sa strace alatom i komentirali razlike izme\u0111u C, Bash i Python programa.","sidebar":"tutorialSidebar"}}}}')}}]);